callee.clean_code:
def average_readings(readings):
    if len(readings) == 0:
        return None
    total = 0.0
    for r in readings:
        try:
            v = float(r)
        except (TypeError, ValueError):
            raise ValueError("invalid reading")
        total += v
    return total / len(readings)

